-- Thùy 26/10 ("Có"): 4 em còn dạng yếu trong các dạng ĐÃ HỌC mà ca bổ trợ đóng TRƯỚC khi luật "xong ca còn dạng yếu ⇒ vào theo dõi" chạy (mig 202610261454)
-- ⇒ đưa vào Đang theo dõi, nguồn sau_bo_tro. Danh sách dạng còn yếu đo bằng _btyeu_dang_con_yeu lúc 26/10 (hàm cũ; chạy ngoài phiên đăng nhập nên ghi sẵn ở đây).
-- Bỏ qua em đã ở theo dõi (unique 1 dòng/HS/môn).
insert into public.bo_tro_theo_doi (hoc_sinh_id, mon, vao_boi, nguon, ghi_chu, so_lieu_vao)
select x.hoc_sinh_id, x.mon, null, 'sau_bo_tro', x.ghi_chu,
       jsonb_build_object('chuyen_de', '[]'::jsonb, 'et_btvn', jsonb_build_object('et', '[]'::jsonb, 'btvn', '[]'::jsonb),
         'sau_bo_tro', jsonb_build_object('case_id', x.case_id, 'ly_do', 'đóng ca ' || x.ngay, 'dang_con_yeu', x.dang_con_yeu, 'so_dang_da_hoc', x.so_da_hoc))
from jsonb_to_recordset($j$[{"hoc_sinh_id":"a9da9b20-fcfa-4a62-b669-edffb2ad6e91","mon":"Toán","case_id":"6e45eaef-c6e1-456b-9b6a-095e0379bf4f","ma_hs":"HS0426","ho_ten":"Phạm Hoàng Thảo My","ngay":"23/10","so_da_hoc":4,"dang_con_yeu":[{"ma_dang":"T105040108","ten_dang":"Viết số đo diện tích dưới dạng số thập phân"}],"ghi_chu":"Sau bổ trợ yếu (đóng ca 23/10) — còn yếu 1 dạng đã học: Viết số đo diện tích dưới dạng số thập phân"},{"hoc_sinh_id":"b24d5d72-8f50-400c-8de3-c570c8db07ed","mon":"Toán","case_id":"ede1becd-38c8-4060-be3a-cd7be7a4bd68","ma_hs":"HS0712","ho_ten":"Nguyễn Thắng Tùng","ngay":"13/10","so_da_hoc":14,"dang_con_yeu":[{"ma_dang":"NDB00810","ten_dang":"Tìm x y ứng dụng GTLN - GTNN Phân thức"}],"ghi_chu":"Sau bổ trợ yếu (đóng ca 13/10) — còn yếu 1 dạng đã học: Tìm x y ứng dụng GTLN - GTNN Phân thức"},{"hoc_sinh_id":"752ac2d8-26c6-45c5-b0ca-f954d566ba28","mon":"Toán","case_id":"28a1c82e-5fd8-4516-825f-9e54107a8356","ma_hs":"HS0578","ho_ten":"Minh Trí","ngay":"17/10","so_da_hoc":9,"dang_con_yeu":[{"ma_dang":"NDB00739","ten_dang":"Tìm điều kiện xác định của biểu thức chứa căn dưới mẫu"},{"ma_dang":"NDB00740","ten_dang":"Tìm điều kiện xác định của biểu thức chứa căn dưới mẫu gồm nhiều biểu thức"},{"ma_dang":"NDB01365","ten_dang":"Bài toán thực tế ứng dụng giải tam giác không vuông"}],"ghi_chu":"Sau bổ trợ yếu (đóng ca 17/10) — còn yếu 3 dạng đã học: Tìm điều kiện xác định của biểu thức chứa căn dưới mẫu; Tìm điều kiện xác định của biểu thức chứa căn dưới mẫu gồm nhiều biểu thức; Bài toán thực tế ứng dụng giải tam giác không vuông"},{"hoc_sinh_id":"7810fe1f-6ed2-40c5-8937-8b5f9c933e8a","mon":"Toán","case_id":"5d9834b0-7011-482b-91d4-b82bf2ca9fec","ma_hs":"HS0557","ho_ten":"Phí Vinh Gia Khiêm","ngay":"17/10","so_da_hoc":5,"dang_con_yeu":[{"ma_dang":"NDB01374","ten_dang":"Cho tan α,cot α ,tính biểu thức đẳng cấp theo sin, cos"},{"ma_dang":"NDB01372","ten_dang":"Góc có số đo cụ thể (góc đặc biệt, góc phụ nhau)"}],"ghi_chu":"Sau bổ trợ yếu (đóng ca 17/10) — còn yếu 2 dạng đã học: Cho tan α,cot α ,tính biểu thức đẳng cấp theo sin, cos; Góc có số đo cụ thể (góc đặc biệt, góc phụ nhau)"}]$j$::jsonb) as x(hoc_sinh_id uuid, mon text, case_id uuid, ngay text, so_da_hoc int, dang_con_yeu jsonb, ghi_chu text)
where not exists (select 1 from public.bo_tro_theo_doi t where t.hoc_sinh_id = x.hoc_sinh_id and t.mon = x.mon and t.trang_thai = 'theo_doi')
  and not exists (select 1 from public.bo_tro_yeu y where y.hoc_sinh_id = x.hoc_sinh_id and y.mon = x.mon and y.trang_thai = 'dang_xu');
